Value.Calculation:
Let ( [

// Same normalizing the widget does: commas, semicolons, returns and spaces all
// separate prefixes; blanks and repeats are dropped; stored as "A, B".
~v = Substitute ( JSONGetElement ( $param ; "TrackingPrefix" ) ; [ ¶ ; "," ] ; [ ";" ; "," ] ; [ Char ( 9 ) ; "," ] ; [ " " ; "," ] ) ;
~l = Substitute ( ~v ; "," ; ¶ )

] ;

Substitute (
	While (
		[ ~i = 1 ; ~o = "" ] ;
		~i ≤ ValueCount ( ~l ) ;
		[
			~p = Trim ( GetValue ( ~l ; ~i ) ) ;
			~o = If ( IsEmpty ( ~p ) or not IsEmpty ( FilterValues ( Upper ( ~o ) ; Upper ( ~p ) ) ) ; ~o ; List ( ~o ; ~p ) ) ;
			~i = ~i + 1
		] ;
		~o
	) ;
	¶ ; ", "
)

)
